public class Main {
    public static int knapsack(int[] weight, int[] value, int W) {
        int n = weight.length;
        int[][] dp = new int[n + 1][W + 1];
for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= W; w++) {
        dp[i][w] = dp[i-1][w];
        if (w >= weight[i-1]) {
            dp[i][w] = _____._____(
                dp[i][w],
                dp[i-1][w - weight[i-1]] + value[i-1]);
        }
    }
}
        return dp[n][W];
    }
    public static void main(String[] args) {
        System.out.println(knapsack(new int[]{2,3,4,5}, new int[]{3,4,5,6}, 8)); // 10
    }
}
